function validate(input) {
  const [{ employees = [] }] = input;
  const ids = new Set();
  for (const [id] of employees) {
    if (id === null) return 'Every employee needs an employee_id.';
    if (ids.has(id)) return `employee_id ${id} appears twice in employees.`;
    ids.add(id);
  }
  return null;
}

