function generate(rand, size) {
  const pick = list => list[Math.floor(rand() * list.length)];
  const names = ['Bob', 'Alice', 'Tatiana', 'Annabelle', 'Jonathan', 'Khaled', 'Mira', 'Omar'];
  const departments = ['Operations', 'Sales', 'Engineering', 'InformationTechnology', 'HumanResources', 'Administration'];
  const employees = [];
  if (size === 'small') {
    // Shuffle a small pool of ids so the stored order differs from id order.
    const ids = Array.from({ length: 20 }, (_, i) => i + 1);
    for (let i = ids.length - 1; i > 0; i--) { const j = Math.floor(rand() * (i + 1)); [ids[i], ids[j]] = [ids[j], ids[i]]; }
    const rows = Math.floor(rand() * 9);
    for (let i = 0; i < rows; i++) employees.push([ids[i], pick(names), pick(departments), 10000 + Math.floor(rand() * 40000)]);
  } else {
    // Stepping by 7919 modulo the prime 100003 gives 2,000 distinct ids in scrambled order.
    const offset = Math.floor(rand() * 100003);
    for (let i = 0; i < 2000; i++) employees.push([1 + (i * 7919 + offset) % 100003, pick(names), pick(departments), 10000 + Math.floor(rand() * 40000)]);
  }
  return [{ employees }];
}
